INSERT INTO `study_materials` VALUES (1,'Computer Fundamentals & MS Office Master Cheat Sheet','computer-fundamentals-ms-office','IT & Computer','Comprehensive cheat sheet covering hardware, OS, MS Word, Excel formulas, and PowerPoint shortcuts.',NULL,NULL,'PDF','2.4 MB','MODULE 1: COMPUTER HARDWARE & ARCHITECTURE\nCPU, ALU, Memory Units (RAM/ROM), Cache, Storage devices.\n\nMODULE 2: MS OFFICE MASTER SHORTCUTS\nCtrl+N (New), Ctrl+S (Save), F4 (Repeat), VLOOKUP, INDEX-MATCH formulas, Pivot Tables.',1,0.00,0.00,0.00,NULL,'ALL_CENTRES','STUDENT_DIRECT',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,13,'2026-10-02 17:07:52','2026-10-11 06:33:23',20.00),(2,'Speed Maths & Vedic Arithmetic 50 Quick Tricks','speed-maths-vedic-arithmetic','Aptitude','50 High-yield calculation tricks for competitive exam quantitative sections.',NULL,'','HTML','1.8 MB','<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#0b1220\">\n<title>Operating Systems — Interactive Notes 2026</title>\n<style>\n:root{\n --bg:#080d17;--panel:#0f1726;--panel2:#131e30;--line:#25334a;--text:#edf5ff;--muted:#9aabc2;\n --cyan:#22d3ee;--blue:#60a5fa;--violet:#a78bfa;--pink:#f472b6;--green:#34d399;\n --yellow:#fbbf24;--orange:#fb923c;--red:#fb7185;\n}\n*{box-sizing:border-box}html{scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--text);font:15px/1.65 Inter,system-ui,-apple-system,Segoe UI,sans-serif}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\n.app{display:grid;grid-template-columns:275px 1fr;min-height:100vh}\naside{position:sticky;top:0;height:100vh;overflow:auto;background:#0a111e;border-right:1px solid var(--line);padding:20px 14px}\n.brand{padding:8px 10px 18px;border-bottom:1px solid var(--line);margin-bottom:14px}\n.brand b{font-size:20px}.brand small{display:block;color:var(--muted);margin-top:3px}\n.search{width:100%;background:#101a2b;border:1px solid var(--line);border-radius:10px;padding:10px;color:var(--text);outline:none}\nnav{margin-top:14px}nav a{display:block;color:#aebbd0;text-decoration:none;padding:8px 10px;border-radius:8px;margin:2px 0}\nnav a:hover,nav a.active{background:#142238;color:#fff;border-left:3px solid var(--cyan)}\nmain{max-width:1300px;width:100%;margin:auto;padding:28px 34px 80px}\n.hero{position:relative;overflow:hidden;border:1px solid var(--line);background:#0d1625;border-radius:22px;padding:42px}\n.hero h1{font-size:clamp(34px,5vw,68px);line-height:1.02;margin:0 0 15px;letter-spacing:-2px}\n.hero h1 span{color:var(--cyan)}\n.hero p{max-width:850px;color:#b4c1d4;font-size:17px}\n.hero-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:25px}\n.stat{border:1px solid var(--line);background:#101b2c;padding:16px;border-radius:14px}\n.stat b{display:block;font-size:25px;color:#fff}.stat small{color:var(--muted)}\n.hero-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}\n.btn{border:1px solid var(--line);background:#142238;color:#fff;border-radius:10px;padding:10px 15px}\n.btn.primary{background:#0891b2;border-color:#22d3ee}.btn:hover{transform:translateY(-2px)}\n.section{margin-top:34px;scroll-margin-top:20px}\n.section-head{display:flex;justify-content:space-between;gap:15px;align-items:end;margin-bottom:15px}\n.section h2{font-size:30px;margin:0}.section-head p{color:var(--muted);margin:3px 0}\n.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px}\n.card h3{margin:0 0 9px;font-size:19px}.card p{color:#b8c5d7}.card li{margin:6px 0}\n.badge{display:inline-block;padding:3px 8px;border:1px solid var(--line);border-radius:999px;color:#b9d8ff;font-size:12px;margin:2px}\n.badge.cyan{color:#a5f3fc;border-color:#155e75}.badge.green{color:#a7f3d0;border-color:#065f46}\n.badge.yellow{color:#fef3c7;border-color:#92400e}.badge.red{color:#ffe4e6;border-color:#9f1239}\n.flow{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:15px 0}\n.node{min-width:100px;text-align:center;padding:11px 14px;border-radius:12px;border:1px solid #334155;background:#162338;font-weight:700}\n.arrow{font-size:22px;color:var(--cyan);animation:arrow 1s infinite}\n@keyframes arrow{50%{transform:translateX(6px)}}\n.note{border-left:3px solid var(--cyan);background:#0d1b2a;padding:12px 15px;color:#c7d4e5;border-radius:0 10px 10px 0}\n.viz{background:#09121f;border:1px solid var(--line);border-radius:16px;padding:18px;overflow:hidden}\n.viz-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:14px}\n.controls{display:flex;flex-wrap:wrap;gap:8px}.controls button,.controls select,.controls input{background:#152238;color:#e8f0fb;border:1px solid #334155;border-radius:8px;padding:8px 10px}\n.stage{min-height:220px;position:relative;border:1px solid #1f2d42;border-radius:12px;background:#0b1422;padding:18px;overflow:hidden}\n.live{width:8px;height:8px;border-radius:50%;background:var(--green);display:inline-block;box-shadow:0 0 0 0 #34d39955;animation:live 1.6s infinite}\n@keyframes live{70%{box-shadow:0 0 0 9px transparent}}\n.process{display:inline-flex;align-items:center;justify-content:center;width:62px;height:42px;border:1px solid #3b82f6;border-radius:10px;background:#162d4a;margin:5px;font-weight:800}\n.process.running{border-color:var(--green);box-shadow:0 0 22px #34d39944;animation:run .8s infinite alternate}\n.process.wait{border-color:var(--yellow)}.process.done{border-color:#64748b;opacity:.55}\n@keyframes run{to{transform:translateY(-5px)}}\n.queue{border:1px dashed #334155;border-radius:10px;padding:12px;min-height:65px;margin:10px 0}\n.cpu{margin:12px auto;border:2px solid var(--cyan);border-radius:15px;width:180px;height:80px;display:grid;place-items:center;background:#102434;box-shadow:0 0 25px #22d3ee20}\n.gantt{display:flex;height:55px;margin-top:20px;border:1px solid #334155;border-radius:8px;overflow:hidden}\n.gantt span{display:grid;place-items:center;border-right:1px solid #0b1220;background:#1d4f72;font-weight:700;min-width:45px}\n.gantt span:nth-child(2n){background:#5b3a72}.gantt span:nth-child(3n){background:#23644e}\n.frames{display:flex;gap:8px;margin:15px 0;flex-wrap:wrap}.frame{width:70px;height:70px;border:1px solid #334155;border-radius:10px;display:grid;place-items:center;background:#111c2d;font-weight:800}\n.frame.hot{border-color:var(--yellow);box-shadow:0 0 18px #fbbf2430;animation:frame .8s infinite alternate}\n.frame.fault{border-color:var(--red)}@keyframes frame{to{transform:translateY(-5px)}}\n.mem{display:flex;gap:3px;align-items:flex-end;height:180px;padding:10px}.page{width:35px;border-radius:5px 5px 0 0;background:#2563eb;animation:page .7s both}.page:nth-child(2n){background:#7c3aed}.page:nth-child(3n){background:#059669}\n@keyframes page{from{height:0;opacity:0}to{opacity:1}}\n.deadlock{position:relative;height:250px}.ring{position:absolute;inset:25px;border:2px dashed #fb718566;border-radius:50%;animation:spin 8s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n.dnode{position:absolute;padding:12px 17px;border:1px solid #fb7185;background:#321827;border-radius:12px;z-index:2}.d1{top:20px;left:15%}.d2{top:20px;right:15%}.d3{bottom:20px;right:15%}.d4{bottom:20px;left:15%}\n.lock{display:inline-grid;place-items:center;width:70px;height:70px;border-radius:50%;border:2px solid var(--violet);background:#251d40;animation:lock 1.5s infinite alternate}\n@keyframes lock{to{box-shadow:0 0 25px #a78bfa44;transform:scale(1.04)}}\n.disk{height:210px;position:relative;border:1px solid #334155;border-radius:12px;overflow:hidden;background:repeating-linear-gradient(90deg,#101b2b 0 44px,#162337 45px 46px)}\n.disk-head{position:absolute;top:0;bottom:0;width:3px;background:var(--pink);left:8%;box-shadow:0 0 14px #f472b655;animation:seek 4s ease-in-out infinite alternate}\n@keyframes seek{to{left:86%}}\n.track-labels{display:flex;justify-content:space-between;color:#7f91aa;font-size:12px;padding:5px}\n.file-tree{font-family:ui-monospace,monospace;color:#bcd0e9;line-height:1.8}\n.file-tree .dir{color:var(--cyan)}.file-tree .file{color:#a7f3d0}\ntable{width:100%;border-collapse:collapse;margin:10px 0}th,td{border:1px solid var(--line);padding:9px;text-align:left}th{background:#152238}td{color:#c1cedf}\n.code{background:#070d16;border:1px solid #1e293b;border-radius:10px;padding:15px;overflow:auto;font:13px/1.7 ui-monospace,monospace;color:#cfe4ff}\n.keyword{color:#f472b6}.fn{color:#22d3ee}.comment{color:#71849e}\n.quiz{border-top:1px solid var(--line);padding-top:15px;margin-top:15px}.option{display:block;width:100%;text-align:left;margin:7px 0;background:#111c2c;color:#d9e4f3;border:1px solid #334155;border-radius:9px;padding:10px}.option:hover{border-color:var(--cyan)}.answer{margin-top:8px;color:#9fe8c7}\n.progress{height:6px;background:#1e293b;border-radius:99px;overflow:hidden}.progress span{display:block;height:100%;width:0;background:var(--cyan);transition:width .6s}\n.reveal{opacity:0;transform:translateY(16px)}.show{opacity:1;transform:none;transition:.7s cubic-bezier(.2,.8,.2,1)}\nfooter{text-align:center;color:#71849e;padding:40px 0}\n@media(max-width:900px){.app{grid-template-columns:1fr}aside{position:relative;height:auto;max-height:360px}.hero-grid{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}main{padding:20px}}\n@media(max-width:560px){.hero{padding:25px}.hero-grid{grid-template-columns:1fr 1fr}.section h2{font-size:24px}}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.001ms!important;transition-duration:.001ms!important;scroll-behavior:auto!important}}\n</style>\n</head>\n<body>\n<div class=\"app\">\n<aside>\n <div class=\"brand\"><b>OS Notes <span style=\"color:#22d3ee\">2026</span></b><small>Interactive Operating Systems</small></div>\n <input class=\"search\" id=\"search\" placeholder=\"Search topics…\">\n <nav id=\"nav\">\n  <a href=\"#overview\">Overview</a><a href=\"#process\">Processes</a><a href=\"#threads\">Threads</a>\n  <a href=\"#scheduling\">CPU Scheduling</a><a href=\"#sync\">Synchronization</a><a href=\"#deadlock\">Deadlocks</a>\n  <a href=\"#memory\">Memory Management</a><a href=\"#virtual\">Virtual Memory</a><a href=\"#files\">File Systems</a>\n  <a href=\"#disk\">Disk Management</a><a href=\"#io\">I/O Systems</a><a href=\"#security\">Security</a>\n  <a href=\"#linux\">Linux / Unix</a><a href=\"#advanced\">Advanced OS</a><a href=\"#cheat\">Cheat Sheet</a><a href=\"#quiz\">Practice</a>\n </nav>\n</aside>\n\n<main>\n<section class=\"hero reveal\">\n <span class=\"badge cyan\">VISUAL LEARNING MODE</span>\n <h1>Operating <span>Systems</span><br>Interactive Notes</h1>\n <p>Learn how an operating system manages CPU time, processes, memory, files, devices and resources through animated models, diagrams, simulators and exam-focused explanations.</p>\n <div class=\"hero-actions\"><a class=\"btn primary\" href=\"#process\">Start Learning</a><a class=\"btn\" href=\"#scheduling\">Open CPU Simulator</a><a class=\"btn\" href=\"#quiz\">Practice Questions</a></div>\n <div class=\"hero-grid\">\n  <div class=\"stat\"><b>15+</b><small>Core Modules</small></div><div class=\"stat\"><b>20+</b><small>Visual Models</small></div>\n  <div class=\"stat\"><b>10+</b><small>Algorithms</small></div><div class=\"stat\"><b>100%</b><small>Offline HTML</small></div>\n </div>\n</section>\n\n<section id=\"overview\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>1. OS Fundamentals</h2><p>The operating system is the manager between applications and hardware.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>What is an Operating System?</h3><p>An OS is system software that controls hardware resources and provides services to application programs. It acts as an abstraction layer so applications do not need to directly manage every hardware detail.</p>\n   <div class=\"flow\"><div class=\"node\">Applications</div><div class=\"arrow\">↓</div><div class=\"node\">System Calls</div><div class=\"arrow\">↓</div><div class=\"node\">Kernel</div><div class=\"arrow\">↓</div><div class=\"node\">Hardware</div></div>\n  </article>\n  <article class=\"card\"><h3>Core responsibilities</h3><ul><li>Process and CPU management</li><li>Memory allocation and virtual memory</li><li>File and storage management</li><li>Device and I/O management</li><li>Protection and security</li><li>Networking and resource sharing</li></ul></article>\n  <article class=\"card\"><h3>Kernel vs User Mode</h3><p><span class=\"badge cyan\">User mode</span> Applications execute with restricted privileges.</p><p><span class=\"badge red\">Kernel mode</span> The kernel can execute privileged operations and access hardware resources.</p><div class=\"note\">A system call provides a controlled transition from user mode to kernel mode.</div></article>\n  <article class=\"card\"><h3>OS services</h3><table><tr><th>Service</th><th>Purpose</th></tr><tr><td>Program execution</td><td>Load and run programs</td></tr><tr><td>I/O</td><td>Communicate with devices</td></tr><tr><td>File system</td><td>Create/read/write files</td></tr><tr><td>Communication</td><td>IPC and networking</td></tr><tr><td>Protection</td><td>Control access to resources</td></tr></table></article>\n </div>\n</section>\n\n<section id=\"process\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>2. Process Management</h2><p>Program + execution state + resources = process.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Process State Model</h3><div class=\"flow\"><div class=\"node\">NEW</div><div class=\"arrow\">→</div><div class=\"node\">READY</div><div class=\"arrow\">→</div><div class=\"node\">RUNNING</div><div class=\"arrow\">→</div><div class=\"node\">TERMINATED</div></div><div class=\"note\">Running → Waiting occurs when a process waits for I/O or another event. Waiting → Ready occurs when the event completes.</div></article>\n  <article class=\"card\"><h3>PCB — Process Control Block</h3><p>The PCB stores the information needed by the OS to manage a process.</p><ul><li>Process ID (PID)</li><li>Process state</li><li>Program counter</li><li>CPU registers</li><li>Scheduling information</li><li>Memory-management information</li><li>I/O status and open files</li></ul></article>\n </div>\n <div class=\"viz\">\n  <div class=\"viz-head\"><h3>Animated Process Lifecycle</h3><span><i class=\"live\"></i> running</span></div>\n  <div class=\"stage\" id=\"processStage\"><div><b>Ready Queue</b><div class=\"queue\" id=\"readyQ\"></div></div><div class=\"cpu\" id=\"cpu\">CPU · idle</div><div><b>Completed</b><div class=\"queue\" id=\"doneQ\"></div></div></div>\n  <div class=\"controls\"><button onclick=\"runProcessDemo()\">Run simulation</button><button onclick=\"resetProcessDemo()\">Reset</button></div>\n </div>\n</section>\n\n<section id=\"threads\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>3. Threads</h2><p>Threads are units of execution inside a process.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Process vs Thread</h3><table><tr><th>Process</th><th>Thread</th></tr><tr><td>Owns resources/address space</td><td>Shares process resources</td></tr><tr><td>More expensive context switch</td><td>Usually cheaper context switch</td></tr><tr><td>Isolation is stronger</td><td>Communication is easier within a process</td></tr></table></article>\n  <article class=\"card\"><h3>Multithreading</h3><p>A multithreaded process can perform multiple activities concurrently. Threads share code, data and open resources while maintaining their own execution state such as registers and stack.</p><div class=\"flow\"><div class=\"node\">Process</div><div class=\"arrow\">→</div><div class=\"node\">Thread A</div><div class=\"node\">Thread B</div><div class=\"node\">Thread C</div></div></article>\n </div>\n</section>\n\n<section id=\"scheduling\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>4. CPU Scheduling</h2><p>Choose which ready process gets the CPU next.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Important metrics</h3><ul><li><b>Turnaround Time</b> = Completion Time − Arrival Time</li><li><b>Waiting Time</b> = Turnaround Time − Burst Time</li><li><b>Response Time</b> = First CPU Start − Arrival Time</li><li><b>Throughput</b> = Completed processes / unit time</li></ul></article>\n  <article class=\"card\"><h3>Scheduling algorithms</h3><p><span class=\"badge cyan\">FCFS</span> First arrival runs first.</p><p><span class=\"badge cyan\">SJF</span> Shortest burst first.</p><p><span class=\"badge yellow\">SRTF</span> Preemptive shortest remaining time.</p><p><span class=\"badge green\">RR</span> Each process receives a time quantum.</p><p><span class=\"badge\">Priority</span> Highest priority is selected according to the chosen priority convention.</p></article>\n </div>\n <div class=\"viz\">\n  <div class=\"viz-head\"><h3>Gantt Chart — Round Robin</h3><span class=\"badge cyan\">Interactive</span></div>\n  <div class=\"controls\"><label>Quantum <input id=\"quantum\" type=\"number\" min=\"1\" value=\"2\" style=\"width:70px\"></label><button onclick=\"runRR()\">Run RR</button><button onclick=\"document.getElementById(\'gantt\').innerHTML=\'\'\">Clear</button></div>\n  <div id=\"gantt\" class=\"gantt\"></div><p id=\"schedInfo\" style=\"color:#9aabc2\"></p>\n </div>\n</section>\n\n<section id=\"sync\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>5. Process Synchronization</h2><p>Coordination is required when concurrent execution accesses shared data.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Critical Section</h3><p>A critical section is the part of a program that accesses shared resources. A correct solution aims for mutual exclusion, progress and bounded waiting.</p><div class=\"flow\"><div class=\"node\">Entry</div><div class=\"arrow\">→</div><div class=\"node\">Critical Section</div><div class=\"arrow\">→</div><div class=\"node\">Exit</div><div class=\"arrow\">→</div><div class=\"node\">Remainder</div></div></article>\n  <article class=\"card\"><h3>Mutex & Semaphore</h3><p><b>Mutex:</b> ownership-based lock commonly used for mutual exclusion.</p><p><b>Semaphore:</b> synchronization primitive represented by a counter and atomic wait/signal operations.</p><div class=\"lock\">LOCK</div></article>\n  <article class=\"card\"><h3>Classic problems</h3><ul><li>Producer–Consumer / Bounded Buffer</li><li>Readers–Writers</li><li>Dining Philosophers</li></ul></article>\n  <article class=\"card\"><h3>Race condition</h3><p>When the result depends on the timing/order of concurrent accesses to shared state. Synchronization controls the order of critical operations.</p></article>\n </div>\n</section>\n\n<section id=\"deadlock\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>6. Deadlocks</h2><p>A set of processes can become permanently blocked while waiting for resources held by each other.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Four necessary conditions</h3><ol><li>Mutual exclusion</li><li>Hold and wait</li><li>No preemption</li><li>Circular wait</li></ol><div class=\"note\">Breaking at least one necessary condition can prevent deadlock.</div></article>\n  <article class=\"card\"><h3>Prevention vs Avoidance vs Detection</h3><p><b>Prevention:</b> constrain resource allocation so a necessary condition cannot hold.</p><p><b>Avoidance:</b> make allocation decisions while maintaining a safe state.</p><p><b>Detection:</b> allow deadlock, then detect and recover.</p></article>\n </div>\n <div class=\"viz\"><h3>Resource Allocation — Circular Wait</h3><div class=\"stage deadlock\"><div class=\"ring\"></div><div class=\"dnode d1\">P1 holds R1</div><div class=\"dnode d2\">R1 waits P2</div><div class=\"dnode d3\">P2 holds R2</div><div class=\"dnode d4\">R2 waits P1</div></div></div>\n <div class=\"card\" style=\"margin-top:15px\"><h3>Banker\'s Algorithm</h3><p>The system grants a request only if the resulting state remains safe. Core data: <b>Available</b>, <b>Max</b>, <b>Allocation</b>, and <b>Need = Max − Allocation</b>.</p><div class=\"flow\"><div class=\"node\">Available</div><div class=\"arrow\">→</div><div class=\"node\">Need check</div><div class=\"arrow\">→</div><div class=\"node\">Pretend allocate</div><div class=\"arrow\">→</div><div class=\"node\">Safe sequence?</div></div></div>\n</section>\n\n<section id=\"memory\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>7. Memory Management</h2><p>Memory management maps processes to physical memory while providing protection and efficient allocation.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Logical vs Physical Address</h3><div class=\"flow\"><div class=\"node\">CPU</div><div class=\"arrow\">→</div><div class=\"node\">Logical Address</div><div class=\"arrow\">→</div><div class=\"node\">MMU</div><div class=\"arrow\">→</div><div class=\"node\">Physical Address</div></div></article>\n  <article class=\"card\"><h3>Fragmentation</h3><p><b>Internal fragmentation:</b> unused space inside an allocated block.</p><p><b>External fragmentation:</b> free memory exists but is split into small non-contiguous pieces.</p></article>\n  <article class=\"card\"><h3>Paging</h3><p>Logical memory is divided into fixed-size pages; physical memory is divided into frames. A page table maps page numbers to frame numbers.</p><div class=\"frames\"><div class=\"frame\">F0</div><div class=\"frame hot\">F1</div><div class=\"frame\">F2</div><div class=\"frame\">F3</div></div></article>\n  <article class=\"card\"><h3>Segmentation</h3><p>A logical address is represented as a segment number and offset. Segments correspond to logical program units such as code, data or stack.</p></article>\n </div>\n</section>\n\n<section id=\"virtual\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>8. Virtual Memory</h2><p>Virtual memory lets processes use an address space larger than available physical RAM.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Page Fault</h3><div class=\"flow\"><div class=\"node\">Reference Page</div><div class=\"arrow\">→</div><div class=\"node\">Page Table</div><div class=\"arrow\">→</div><div class=\"node\">Not in RAM</div><div class=\"arrow\">→</div><div class=\"node\">Page Fault</div></div><p>The OS loads the required page from secondary storage and updates the page table.</p></article>\n  <article class=\"card\"><h3>TLB</h3><p>The Translation Lookaside Buffer caches recent page-table translations. A TLB hit avoids an additional page-table lookup.</p></article>\n </div>\n <div class=\"viz\"><div class=\"viz-head\"><h3>Page Replacement Visualizer</h3><span class=\"badge yellow\">FIFO / LRU concept</span></div><div class=\"controls\"><button onclick=\"pageDemo(\'FIFO\')\">FIFO</button><button onclick=\"pageDemo(\'LRU\')\">LRU</button><button onclick=\"resetPages()\">Reset</button></div><div class=\"frames\" id=\"pageFrames\"><div class=\"frame\">—</div><div class=\"frame\">—</div><div class=\"frame\">—</div></div><p id=\"pageInfo\" style=\"color:#9aabc2\">Click an algorithm to step through reference pages.</p></div>\n</section>\n\n<section id=\"files\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>9. File Systems</h2><p>The file system organizes persistent data into files, directories and metadata.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>File operations</h3><div class=\"flow\"><div class=\"node\">Create</div><div class=\"node\">Open</div><div class=\"node\">Read</div><div class=\"node\">Write</div><div class=\"node\">Close</div><div class=\"node\">Delete</div></div></article>\n  <article class=\"card\"><h3>Directory structures</h3><div class=\"file-tree\"><span class=\"dir\">/home</span><br>├── <span class=\"dir\">user/</span><br>│ ├── <span class=\"file\">notes.txt</span><br>│ └── <span class=\"file\">app.js</span><br>└── <span class=\"dir\">projects/</span></div></article>\n  <article class=\"card\"><h3>File allocation</h3><p><b>Contiguous:</b> file occupies consecutive blocks.</p><p><b>Linked:</b> each block points to the next block.</p><p><b>Indexed:</b> an index block stores pointers to file blocks.</p></article>\n  <article class=\"card\"><h3>Inode concept</h3><p>Unix-like file systems use inode metadata to describe a file, including ownership, permissions, timestamps, size and pointers to data blocks.</p></article>\n </div>\n</section>\n\n<section id=\"disk\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>10. Disk Management</h2><p>Disk scheduling determines the order in which pending disk requests are served.</p></div></div>\n <div class=\"grid\"><article class=\"card\"><h3>Algorithms</h3><p><span class=\"badge cyan\">FCFS</span> Serve in arrival order.</p><p><span class=\"badge yellow\">SSTF</span> Serve the nearest request.</p><p><span class=\"badge green\">SCAN</span> Move like an elevator toward one end, then reverse.</p><p><span class=\"badge\">C-SCAN</span> Move in one direction and wrap around.</p><p><span class=\"badge\">LOOK / C-LOOK</span> Similar ideas but stop at the final pending request.</p></article>\n <article class=\"card\"><h3>Why scheduling matters</h3><p>Seek time can dominate disk access. Reordering requests can reduce head movement and improve throughput, though policies may introduce fairness or starvation trade-offs.</p></article></div>\n <div class=\"viz\"><h3>Animated Disk Head</h3><div class=\"disk\"><div class=\"disk-head\"></div></div><div class=\"track-labels\"><span>0</span><span>25</span><span>50</span><span>75</span><span>100</span></div></div>\n</section>\n\n<section id=\"io\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>11. I/O Systems</h2><p>The OS coordinates CPU, memory and external devices.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Interrupt-driven I/O</h3><div class=\"flow\"><div class=\"node\">Device</div><div class=\"arrow\">→</div><div class=\"node\">Interrupt</div><div class=\"arrow\">→</div><div class=\"node\">CPU</div><div class=\"arrow\">→</div><div class=\"node\">ISR</div></div></article>\n  <article class=\"card\"><h3>DMA</h3><p>Direct Memory Access allows a controller to transfer blocks between a device and memory with limited CPU involvement.</p></article>\n  <article class=\"card\"><h3>Buffering, Caching, Spooling</h3><p><b>Buffering:</b> temporary data area for rate mismatch.</p><p><b>Caching:</b> retain frequently/recently used data for faster access.</p><p><b>Spooling:</b> queue work for a device, classically print jobs.</p></article>\n </div>\n</section>\n\n<section id=\"security\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>12. Protection & Security</h2><p>Security controls who can access resources and what operations they may perform.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Authentication vs Authorization</h3><div class=\"flow\"><div class=\"node\">Identity</div><div class=\"arrow\">→</div><div class=\"node\">Authentication</div><div class=\"arrow\">→</div><div class=\"node\">Authorization</div><div class=\"arrow\">→</div><div class=\"node\">Resource</div></div><p>Authentication establishes identity; authorization determines permitted actions.</p></article>\n  <article class=\"card\"><h3>Least Privilege</h3><p>Give a process, user or service only the permissions required to perform its task. This limits the impact of compromise or mistakes.</p></article>\n </div>\n</section>\n\n<section id=\"linux\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>13. Linux / Unix Concepts</h2><p>Practical OS concepts through a Unix-like system model.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Useful commands</h3><div class=\"code\"><span class=\"comment\"># processes</span>\nps aux\ntop\nkill PID\n\n<span class=\"comment\"># files</span>\nls -la\ncd project\nmkdir demo\ncat file.txt\n\n<span class=\"comment\"># permissions</span>\nchmod 755 script.sh\nchown user:group file</div></article>\n  <article class=\"card\"><h3>Process & filesystem model</h3><div class=\"flow\"><div class=\"node\">Shell</div><div class=\"arrow\">→</div><div class=\"node\">System Call</div><div class=\"arrow\">→</div><div class=\"node\">Kernel</div><div class=\"arrow\">→</div><div class=\"node\">Resource</div></div><p>Linux exposes many kernel objects and runtime details through virtual file systems such as <code>/proc</code>.</p></article>\n </div>\n</section>\n\n<section id=\"advanced\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>14. Advanced OS Concepts</h2><p>Concepts used in modern servers, cloud platforms and embedded systems.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Virtualization</h3><p>A hypervisor provides an abstraction that allows multiple virtual machines to share physical hardware.</p><div class=\"flow\"><div class=\"node\">VM 1</div><div class=\"node\">VM 2</div><div class=\"node\">VM 3</div><div class=\"arrow\">↓</div><div class=\"node\">Hypervisor</div><div class=\"arrow\">↓</div><div class=\"node\">Hardware</div></div></article>\n  <article class=\"card\"><h3>Containers</h3><p>Containers isolate application processes while sharing the host kernel. They are lighter than full virtual machines because they do not normally require a separate guest kernel.</p></article>\n  <article class=\"card\"><h3>Real-Time OS</h3><p>RTOS designs prioritize predictable response and meeting timing constraints. Hard and soft real-time systems differ in the consequences of missing deadlines.</p></article>\n  <article class=\"card\"><h3>Multiprocessor & Distributed Systems</h3><p>Multiprocessor systems use multiple processing units in one computer system. Distributed systems coordinate independent machines through communication networks.</p></article>\n </div>\n</section>\n\n<section id=\"cheat\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>15. Exam Cheat Sheet</h2><p>Fast revision of high-frequency formulas and concepts.</p></div></div>\n <div class=\"card\"><table>\n <tr><th>Topic</th><th>Remember</th></tr>\n <tr><td>Process</td><td>Program in execution; PCB stores process management information.</td></tr>\n <tr><td>Context switch</td><td>Save state of one process/thread and restore another.</td></tr>\n <tr><td>Waiting time</td><td>Turnaround − Burst time.</td></tr>\n <tr><td>Turnaround</td><td>Completion − Arrival.</td></tr>\n <tr><td>Paging</td><td>Pages map to fixed-size physical frames.</td></tr>\n <tr><td>Page fault</td><td>Referenced page is not currently in physical memory.</td></tr>\n <tr><td>TLB</td><td>Cache of recent address translations.</td></tr>\n <tr><td>Deadlock</td><td>Mutual exclusion + hold/wait + no preemption + circular wait.</td></tr>\n <tr><td>Semaphore</td><td>Synchronization primitive supporting atomic wait/signal operations.</td></tr>\n <tr><td>DMA</td><td>Device controller transfers data with reduced CPU involvement.</td></tr>\n </table></div>\n</section>\n\n<section id=\"quiz\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>16. Practice Quiz</h2><p>Test your understanding.</p></div></div>\n <div id=\"quizBox\" class=\"grid\"></div>\n <div class=\"card\" style=\"margin-top:15px\"><b>Progress</b><div class=\"progress\"><span id=\"quizProgress\"></span></div><p id=\"score\" style=\"color:#9aabc2\">0 / 5 answered correctly</p></div>\n</section>\n<footer>Operating Systems — Interactive Notes 2026 · Standalone HTML · Visualize → Explain → Interact → Practice</footer>\n</main>\n</div>\n\n<script>\nconst qs=s=>document.querySelector(s), qsa=s=>[...document.querySelectorAll(s)];\n\nconst procNames=[\'P1\',\'P2\',\'P3\',\'P4\']; let procTimer;\nfunction resetProcessDemo(){\n clearInterval(procTimer); qs(\'#readyQ\').innerHTML=procNames.map(x=>\'<span class=\"process\">\'+x+\'</span>\').join(\'\');\n qs(\'#cpu\').textContent=\'CPU · idle\'; qs(\'#doneQ\').innerHTML=\'\';\n}\nfunction runProcessDemo(){\n resetProcessDemo(); let i=0;\n procTimer=setInterval(()=>{\n  if(i>0){qs(\'#doneQ\').insertAdjacentHTML(\'beforeend\',\'<span class=\"process done\">\'+procNames[i-1]+\'</span>\')}\n  qsa(\'#readyQ .process\').forEach(x=>x.classList.remove(\'running\'));\n  if(i<procNames.length){\n   const p=qsa(\'#readyQ .process\')[0];\n   if(p){p.classList.add(\'running\');qs(\'#cpu\').textContent=\'CPU · \'+p.textContent}\n   i++;\n  }else{clearInterval(procTimer);qs(\'#cpu\').textContent=\'CPU · idle\'}\n },900);\n}\n\nfunction runRR(){\n const q=Math.max(1,+qs(\'#quantum\').value||2), jobs=[[\'P1\',5],[\'P2\',4],[\'P3\',2]];\n let t=0, out=[], arr=jobs.map(x=>[x[0],x[1]]);\n while(arr.some(x=>x[1]>0)){\n  for(const x of arr) if(x[1]>0){const run=Math.min(q,x[1]);out.push([x[0],run,t]);x[1]-=run;t+=run}\n }\n qs(\'#gantt\').innerHTML=out.map(x=>\'<span style=\"flex:\'+x[1]+\'\">\'+x[0]+\'<small style=\"font-size:10px;display:block\">\'+x[2]+\'–\'+(x[2]+x[1])+\'</small></span>\').join(\'\');\n qs(\'#schedInfo\').textContent=\'Quantum \'+q+\' · Total CPU time \'+t+\' units · Each process receives CPU slices in round-robin order.\';\n}\n\nlet pageState={refs:[1,2,3,4,1,5,2,1,3,4],i:0,frames:[],last:[]};\nfunction resetPages(){pageState.i=0;pageState.frames=[];pageState.last=[];qs(\'#pageFrames\').innerHTML=\'<div class=\"frame\">—</div><div class=\"frame\">—</div><div class=\"frame\">—</div>\';qs(\'#pageInfo\').textContent=\'Reference string: 1 2 3 4 1 5 2 1 3 4\'}\nfunction pageDemo(mode){\n resetPages(); let steps=0;\n const timer=setInterval(()=>{\n  if(pageState.i>=pageState.refs.length){clearInterval(timer);return}\n  const p=pageState.refs[pageState.i++]; let hit=pageState.frames.includes(p);\n  if(!hit){\n   if(pageState.frames.length<3) pageState.frames.push(p);\n   else if(mode===\'FIFO\') pageState.frames.shift(),pageState.frames.push(p);\n   else {\n    let idx=pageState.frames.map(x=>pageState.last.lastIndexOf(x));\n    let replace=idx.indexOf(Math.min(...idx)); pageState.frames[replace]=p;\n   }\n  }\n  pageState.last.push(p); steps++;\n  qs(\'#pageFrames\').innerHTML=pageState.frames.map((x,j)=>\'<div class=\"frame \'+(hit?\'\':\'hot\')+\'\">\'+x+\'</div>\').join(\'\');\n  qs(\'#pageInfo\').textContent=mode+\' · reference \'+p+\' · \'+(hit?\'HIT\':\'PAGE FAULT\')+\' · step \'+steps;\n },650);\n}\n\nconst questions=[\n [\'Which structure stores process management information?\',[\'PCB\',\'TLB\',\'Inode\',\'DMA\'],\'PCB\'],\n [\'Which scheduling algorithm uses a time quantum?\',[\'SJF\',\'Round Robin\',\'FCFS\',\'SCAN\'],\'Round Robin\'],\n [\'Which condition is necessary for deadlock?\',[\'Caching\',\'Circular wait\',\'DMA\',\'Paging\'],\'Circular wait\'],\n [\'What does a TLB cache?\',[\'Files\',\'CPU instructions\',\'Address translations\',\'Disk blocks\'],\'Address translations\'],\n [\'What does DMA reduce?\',[\'File size\',\'CPU involvement in data transfer\',\'RAM capacity\',\'Process count\'],\'CPU involvement in data transfer\']\n];\nlet score=0,answered=0;\nqs(\'#quizBox\').innerHTML=questions.map((q,i)=>`<article class=\"card quiz\"><h3>${i+1}. ${q[0]}</h3>${q[1].map(o=>`<button class=\"option\" onclick=\"answer(this,\'${o.replace(/\'/g,\"\\\\\'\")}\',\'${q[2].replace(/\'/g,\"\\\\\'\")}\')\">${o}</button>`).join(\'\')}<div class=\"answer\" id=\"ans${i}\"></div></article>`).join(\'\');\nfunction answer(btn,val,correct){\n const box=btn.closest(\'.quiz\'), ans=box.querySelector(\'.answer\');\n if(box.dataset.done)return;box.dataset.done=1;answered++;\n if(val===correct){score++;btn.style.borderColor=\'#34d399\';btn.style.background=\'#0c2b25\';ans.textContent=\'Correct — \'+correct+\'.\'}\n else {btn.style.borderColor=\'#fb7185\';btn.style.background=\'#321827\';ans.textContent=\'Correct answer: \'+correct+\'.\'}\n qs(\'#score\').textContent=score+\' / 5 answered correctly\';qs(\'#quizProgress\').style.width=(answered/5*100)+\'%\';\n}\n\nqs(\'#search\').addEventListener(\'input\',e=>{\n const term=e.target.value.toLowerCase();\n qsa(\'main .section\').forEach(s=>{s.style.display=(!term||s.innerText.toLowerCase().includes(term))?\'\':\'none\'});\n});\nconst observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add(\'show\')}),{threshold:.08});\nqsa(\'.reveal\').forEach(x=>observer.observe(x));\nresetProcessDemo();resetPages();\n</script>\n</body>\n</html>',1,0.00,0.00,0.00,NULL,'ALL_CENTRES','STUDENT_DIRECT',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,54,'2026-10-02 17:07:52','2026-10-04 12:35:47',20.00),(3,'Tally Prime Voucher Shortcuts & GST Tax Master Chart','tally-prime-gst-shortcuts','Accounting','Complete reference handbook for Tally Prime, GST filing, ledger creation, and voucher types.',NULL,'','PDF','3.1 MB','TALLY PRIME KEYS:\nF4: Contra | F5: Payment | F6: Receipt | F7: Journal | F8: Sales | F9: Purchase\nGST Types: CGST, SGST, IGST calculations and tax invoice formats.',0,49.00,0.00,0.00,NULL,'ALL_CENTRES','CENTER_PURCHASE',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,12,'2026-10-02 17:07:52','2026-10-04 13:32:34',20.00),(4,'Banking Awareness & RBI Monetary Policy Handbook 2026','banking-awareness-rbi-monetary-policy','Banking','In-depth monetary policy rates, repo, reverse repo, CRR, SLR, and banking regulations guide.',NULL,'','PDF','4.2 MB','RBI MONETARY POLICY 2026:\nCRR: 4.50% | SLR: 18.00% | Repo Rate: 6.50% | Reverse Repo: 3.35%\nBanking Ombudsman Scheme and priority sector lending norms.',0,100.00,100.00,109.00,NULL,'ALL_CENTRES','CENTER_PURCHASE',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,9,'2026-10-02 17:07:52','2026-10-04 13:32:26',20.00),(5,'Advanced Data Structures & Algorithms Note 2026','advanced-data-structures-algorithms-note-2026-764','Computer Science','Master trees, graphs, dynamic programming, and asymptotic analysis.',NULL,'','PDF','2.5 MB','UNIT 1: BINARY SEARCH TREES & AVL BALANCING\nUNIT 2: GRAPH TRAVERSALS (BFS & DFS)\nUNIT 3: DYNAMIC PROGRAMMING RECURRENCE RELATIONS',0,100.00,0.00,100.00,NULL,'ALL_CENTRES','CENTER_PURCHASE',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,7,'2026-10-02 17:14:40','2026-10-04 13:32:31',20.00),(6,'Center Exclusive B2B Note: Hardware & Networking Guide','center-exclusive-b2b-note-hardware-networking-guide-933','IT & Computer','Distributed by authorized study centers to their students.',NULL,'','HTML','2.5 MB','<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#0b1220\">\n<title>Operating Systems — Interactive Notes 2026</title>\n<style>\n:root{\n --bg:#080d17;--panel:#0f1726;--panel2:#131e30;--line:#25334a;--text:#edf5ff;--muted:#9aabc2;\n --cyan:#22d3ee;--blue:#60a5fa;--violet:#a78bfa;--pink:#f472b6;--green:#34d399;\n --yellow:#fbbf24;--orange:#fb923c;--red:#fb7185;\n}\n*{box-sizing:border-box}html{scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--text);font:15px/1.65 Inter,system-ui,-apple-system,Segoe UI,sans-serif}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\n.app{display:grid;grid-template-columns:275px 1fr;min-height:100vh}\naside{position:sticky;top:0;height:100vh;overflow:auto;background:#0a111e;border-right:1px solid var(--line);padding:20px 14px}\n.brand{padding:8px 10px 18px;border-bottom:1px solid var(--line);margin-bottom:14px}\n.brand b{font-size:20px}.brand small{display:block;color:var(--muted);margin-top:3px}\n.search{width:100%;background:#101a2b;border:1px solid var(--line);border-radius:10px;padding:10px;color:var(--text);outline:none}\nnav{margin-top:14px}nav a{display:block;color:#aebbd0;text-decoration:none;padding:8px 10px;border-radius:8px;margin:2px 0}\nnav a:hover,nav a.active{background:#142238;color:#fff;border-left:3px solid var(--cyan)}\nmain{max-width:1300px;width:100%;margin:auto;padding:28px 34px 80px}\n.hero{position:relative;overflow:hidden;border:1px solid var(--line);background:#0d1625;border-radius:22px;padding:42px}\n.hero h1{font-size:clamp(34px,5vw,68px);line-height:1.02;margin:0 0 15px;letter-spacing:-2px}\n.hero h1 span{color:var(--cyan)}\n.hero p{max-width:850px;color:#b4c1d4;font-size:17px}\n.hero-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:25px}\n.stat{border:1px solid var(--line);background:#101b2c;padding:16px;border-radius:14px}\n.stat b{display:block;font-size:25px;color:#fff}.stat small{color:var(--muted)}\n.hero-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}\n.btn{border:1px solid var(--line);background:#142238;color:#fff;border-radius:10px;padding:10px 15px}\n.btn.primary{background:#0891b2;border-color:#22d3ee}.btn:hover{transform:translateY(-2px)}\n.section{margin-top:34px;scroll-margin-top:20px}\n.section-head{display:flex;justify-content:space-between;gap:15px;align-items:end;margin-bottom:15px}\n.section h2{font-size:30px;margin:0}.section-head p{color:var(--muted);margin:3px 0}\n.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px}\n.card h3{margin:0 0 9px;font-size:19px}.card p{color:#b8c5d7}.card li{margin:6px 0}\n.badge{display:inline-block;padding:3px 8px;border:1px solid var(--line);border-radius:999px;color:#b9d8ff;font-size:12px;margin:2px}\n.badge.cyan{color:#a5f3fc;border-color:#155e75}.badge.green{color:#a7f3d0;border-color:#065f46}\n.badge.yellow{color:#fef3c7;border-color:#92400e}.badge.red{color:#ffe4e6;border-color:#9f1239}\n.flow{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:15px 0}\n.node{min-width:100px;text-align:center;padding:11px 14px;border-radius:12px;border:1px solid #334155;background:#162338;font-weight:700}\n.arrow{font-size:22px;color:var(--cyan);animation:arrow 1s infinite}\n@keyframes arrow{50%{transform:translateX(6px)}}\n.note{border-left:3px solid var(--cyan);background:#0d1b2a;padding:12px 15px;color:#c7d4e5;border-radius:0 10px 10px 0}\n.viz{background:#09121f;border:1px solid var(--line);border-radius:16px;padding:18px;overflow:hidden}\n.viz-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:14px}\n.controls{display:flex;flex-wrap:wrap;gap:8px}.controls button,.controls select,.controls input{background:#152238;color:#e8f0fb;border:1px solid #334155;border-radius:8px;padding:8px 10px}\n.stage{min-height:220px;position:relative;border:1px solid #1f2d42;border-radius:12px;background:#0b1422;padding:18px;overflow:hidden}\n.live{width:8px;height:8px;border-radius:50%;background:var(--green);display:inline-block;box-shadow:0 0 0 0 #34d39955;animation:live 1.6s infinite}\n@keyframes live{70%{box-shadow:0 0 0 9px transparent}}\n.process{display:inline-flex;align-items:center;justify-content:center;width:62px;height:42px;border:1px solid #3b82f6;border-radius:10px;background:#162d4a;margin:5px;font-weight:800}\n.process.running{border-color:var(--green);box-shadow:0 0 22px #34d39944;animation:run .8s infinite alternate}\n.process.wait{border-color:var(--yellow)}.process.done{border-color:#64748b;opacity:.55}\n@keyframes run{to{transform:translateY(-5px)}}\n.queue{border:1px dashed #334155;border-radius:10px;padding:12px;min-height:65px;margin:10px 0}\n.cpu{margin:12px auto;border:2px solid var(--cyan);border-radius:15px;width:180px;height:80px;display:grid;place-items:center;background:#102434;box-shadow:0 0 25px #22d3ee20}\n.gantt{display:flex;height:55px;margin-top:20px;border:1px solid #334155;border-radius:8px;overflow:hidden}\n.gantt span{display:grid;place-items:center;border-right:1px solid #0b1220;background:#1d4f72;font-weight:700;min-width:45px}\n.gantt span:nth-child(2n){background:#5b3a72}.gantt span:nth-child(3n){background:#23644e}\n.frames{display:flex;gap:8px;margin:15px 0;flex-wrap:wrap}.frame{width:70px;height:70px;border:1px solid #334155;border-radius:10px;display:grid;place-items:center;background:#111c2d;font-weight:800}\n.frame.hot{border-color:var(--yellow);box-shadow:0 0 18px #fbbf2430;animation:frame .8s infinite alternate}\n.frame.fault{border-color:var(--red)}@keyframes frame{to{transform:translateY(-5px)}}\n.mem{display:flex;gap:3px;align-items:flex-end;height:180px;padding:10px}.page{width:35px;border-radius:5px 5px 0 0;background:#2563eb;animation:page .7s both}.page:nth-child(2n){background:#7c3aed}.page:nth-child(3n){background:#059669}\n@keyframes page{from{height:0;opacity:0}to{opacity:1}}\n.deadlock{position:relative;height:250px}.ring{position:absolute;inset:25px;border:2px dashed #fb718566;border-radius:50%;animation:spin 8s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n.dnode{position:absolute;padding:12px 17px;border:1px solid #fb7185;background:#321827;border-radius:12px;z-index:2}.d1{top:20px;left:15%}.d2{top:20px;right:15%}.d3{bottom:20px;right:15%}.d4{bottom:20px;left:15%}\n.lock{display:inline-grid;place-items:center;width:70px;height:70px;border-radius:50%;border:2px solid var(--violet);background:#251d40;animation:lock 1.5s infinite alternate}\n@keyframes lock{to{box-shadow:0 0 25px #a78bfa44;transform:scale(1.04)}}\n.disk{height:210px;position:relative;border:1px solid #334155;border-radius:12px;overflow:hidden;background:repeating-linear-gradient(90deg,#101b2b 0 44px,#162337 45px 46px)}\n.disk-head{position:absolute;top:0;bottom:0;width:3px;background:var(--pink);left:8%;box-shadow:0 0 14px #f472b655;animation:seek 4s ease-in-out infinite alternate}\n@keyframes seek{to{left:86%}}\n.track-labels{display:flex;justify-content:space-between;color:#7f91aa;font-size:12px;padding:5px}\n.file-tree{font-family:ui-monospace,monospace;color:#bcd0e9;line-height:1.8}\n.file-tree .dir{color:var(--cyan)}.file-tree .file{color:#a7f3d0}\ntable{width:100%;border-collapse:collapse;margin:10px 0}th,td{border:1px solid var(--line);padding:9px;text-align:left}th{background:#152238}td{color:#c1cedf}\n.code{background:#070d16;border:1px solid #1e293b;border-radius:10px;padding:15px;overflow:auto;font:13px/1.7 ui-monospace,monospace;color:#cfe4ff}\n.keyword{color:#f472b6}.fn{color:#22d3ee}.comment{color:#71849e}\n.quiz{border-top:1px solid var(--line);padding-top:15px;margin-top:15px}.option{display:block;width:100%;text-align:left;margin:7px 0;background:#111c2c;color:#d9e4f3;border:1px solid #334155;border-radius:9px;padding:10px}.option:hover{border-color:var(--cyan)}.answer{margin-top:8px;color:#9fe8c7}\n.progress{height:6px;background:#1e293b;border-radius:99px;overflow:hidden}.progress span{display:block;height:100%;width:0;background:var(--cyan);transition:width .6s}\n.reveal{opacity:0;transform:translateY(16px)}.show{opacity:1;transform:none;transition:.7s cubic-bezier(.2,.8,.2,1)}\nfooter{text-align:center;color:#71849e;padding:40px 0}\n@media(max-width:900px){.app{grid-template-columns:1fr}aside{position:relative;height:auto;max-height:360px}.hero-grid{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}main{padding:20px}}\n@media(max-width:560px){.hero{padding:25px}.hero-grid{grid-template-columns:1fr 1fr}.section h2{font-size:24px}}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.001ms!important;transition-duration:.001ms!important;scroll-behavior:auto!important}}\n</style>\n</head>\n<body>\n<div class=\"app\">\n<aside>\n <div class=\"brand\"><b>OS Notes <span style=\"color:#22d3ee\">2026</span></b><small>Interactive Operating Systems</small></div>\n <input class=\"search\" id=\"search\" placeholder=\"Search topics…\">\n <nav id=\"nav\">\n  <a href=\"#overview\">Overview</a><a href=\"#process\">Processes</a><a href=\"#threads\">Threads</a>\n  <a href=\"#scheduling\">CPU Scheduling</a><a href=\"#sync\">Synchronization</a><a href=\"#deadlock\">Deadlocks</a>\n  <a href=\"#memory\">Memory Management</a><a href=\"#virtual\">Virtual Memory</a><a href=\"#files\">File Systems</a>\n  <a href=\"#disk\">Disk Management</a><a href=\"#io\">I/O Systems</a><a href=\"#security\">Security</a>\n  <a href=\"#linux\">Linux / Unix</a><a href=\"#advanced\">Advanced OS</a><a href=\"#cheat\">Cheat Sheet</a><a href=\"#quiz\">Practice</a>\n </nav>\n</aside>\n\n<main>\n<section class=\"hero reveal\">\n <span class=\"badge cyan\">VISUAL LEARNING MODE</span>\n <h1>Operating <span>Systems</span><br>Interactive Notes</h1>\n <p>Learn how an operating system manages CPU time, processes, memory, files, devices and resources through animated models, diagrams, simulators and exam-focused explanations.</p>\n <div class=\"hero-actions\"><a class=\"btn primary\" href=\"#process\">Start Learning</a><a class=\"btn\" href=\"#scheduling\">Open CPU Simulator</a><a class=\"btn\" href=\"#quiz\">Practice Questions</a></div>\n <div class=\"hero-grid\">\n  <div class=\"stat\"><b>15+</b><small>Core Modules</small></div><div class=\"stat\"><b>20+</b><small>Visual Models</small></div>\n  <div class=\"stat\"><b>10+</b><small>Algorithms</small></div><div class=\"stat\"><b>100%</b><small>Offline HTML</small></div>\n </div>\n</section>\n\n<section id=\"overview\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>1. OS Fundamentals</h2><p>The operating system is the manager between applications and hardware.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>What is an Operating System?</h3><p>An OS is system software that controls hardware resources and provides services to application programs. It acts as an abstraction layer so applications do not need to directly manage every hardware detail.</p>\n   <div class=\"flow\"><div class=\"node\">Applications</div><div class=\"arrow\">↓</div><div class=\"node\">System Calls</div><div class=\"arrow\">↓</div><div class=\"node\">Kernel</div><div class=\"arrow\">↓</div><div class=\"node\">Hardware</div></div>\n  </article>\n  <article class=\"card\"><h3>Core responsibilities</h3><ul><li>Process and CPU management</li><li>Memory allocation and virtual memory</li><li>File and storage management</li><li>Device and I/O management</li><li>Protection and security</li><li>Networking and resource sharing</li></ul></article>\n  <article class=\"card\"><h3>Kernel vs User Mode</h3><p><span class=\"badge cyan\">User mode</span> Applications execute with restricted privileges.</p><p><span class=\"badge red\">Kernel mode</span> The kernel can execute privileged operations and access hardware resources.</p><div class=\"note\">A system call provides a controlled transition from user mode to kernel mode.</div></article>\n  <article class=\"card\"><h3>OS services</h3><table><tr><th>Service</th><th>Purpose</th></tr><tr><td>Program execution</td><td>Load and run programs</td></tr><tr><td>I/O</td><td>Communicate with devices</td></tr><tr><td>File system</td><td>Create/read/write files</td></tr><tr><td>Communication</td><td>IPC and networking</td></tr><tr><td>Protection</td><td>Control access to resources</td></tr></table></article>\n </div>\n</section>\n\n<section id=\"process\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>2. Process Management</h2><p>Program + execution state + resources = process.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Process State Model</h3><div class=\"flow\"><div class=\"node\">NEW</div><div class=\"arrow\">→</div><div class=\"node\">READY</div><div class=\"arrow\">→</div><div class=\"node\">RUNNING</div><div class=\"arrow\">→</div><div class=\"node\">TERMINATED</div></div><div class=\"note\">Running → Waiting occurs when a process waits for I/O or another event. Waiting → Ready occurs when the event completes.</div></article>\n  <article class=\"card\"><h3>PCB — Process Control Block</h3><p>The PCB stores the information needed by the OS to manage a process.</p><ul><li>Process ID (PID)</li><li>Process state</li><li>Program counter</li><li>CPU registers</li><li>Scheduling information</li><li>Memory-management information</li><li>I/O status and open files</li></ul></article>\n </div>\n <div class=\"viz\">\n  <div class=\"viz-head\"><h3>Animated Process Lifecycle</h3><span><i class=\"live\"></i> running</span></div>\n  <div class=\"stage\" id=\"processStage\"><div><b>Ready Queue</b><div class=\"queue\" id=\"readyQ\"></div></div><div class=\"cpu\" id=\"cpu\">CPU · idle</div><div><b>Completed</b><div class=\"queue\" id=\"doneQ\"></div></div></div>\n  <div class=\"controls\"><button onclick=\"runProcessDemo()\">Run simulation</button><button onclick=\"resetProcessDemo()\">Reset</button></div>\n </div>\n</section>\n\n<section id=\"threads\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>3. Threads</h2><p>Threads are units of execution inside a process.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Process vs Thread</h3><table><tr><th>Process</th><th>Thread</th></tr><tr><td>Owns resources/address space</td><td>Shares process resources</td></tr><tr><td>More expensive context switch</td><td>Usually cheaper context switch</td></tr><tr><td>Isolation is stronger</td><td>Communication is easier within a process</td></tr></table></article>\n  <article class=\"card\"><h3>Multithreading</h3><p>A multithreaded process can perform multiple activities concurrently. Threads share code, data and open resources while maintaining their own execution state such as registers and stack.</p><div class=\"flow\"><div class=\"node\">Process</div><div class=\"arrow\">→</div><div class=\"node\">Thread A</div><div class=\"node\">Thread B</div><div class=\"node\">Thread C</div></div></article>\n </div>\n</section>\n\n<section id=\"scheduling\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>4. CPU Scheduling</h2><p>Choose which ready process gets the CPU next.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Important metrics</h3><ul><li><b>Turnaround Time</b> = Completion Time − Arrival Time</li><li><b>Waiting Time</b> = Turnaround Time − Burst Time</li><li><b>Response Time</b> = First CPU Start − Arrival Time</li><li><b>Throughput</b> = Completed processes / unit time</li></ul></article>\n  <article class=\"card\"><h3>Scheduling algorithms</h3><p><span class=\"badge cyan\">FCFS</span> First arrival runs first.</p><p><span class=\"badge cyan\">SJF</span> Shortest burst first.</p><p><span class=\"badge yellow\">SRTF</span> Preemptive shortest remaining time.</p><p><span class=\"badge green\">RR</span> Each process receives a time quantum.</p><p><span class=\"badge\">Priority</span> Highest priority is selected according to the chosen priority convention.</p></article>\n </div>\n <div class=\"viz\">\n  <div class=\"viz-head\"><h3>Gantt Chart — Round Robin</h3><span class=\"badge cyan\">Interactive</span></div>\n  <div class=\"controls\"><label>Quantum <input id=\"quantum\" type=\"number\" min=\"1\" value=\"2\" style=\"width:70px\"></label><button onclick=\"runRR()\">Run RR</button><button onclick=\"document.getElementById(\'gantt\').innerHTML=\'\'\">Clear</button></div>\n  <div id=\"gantt\" class=\"gantt\"></div><p id=\"schedInfo\" style=\"color:#9aabc2\"></p>\n </div>\n</section>\n\n<section id=\"sync\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>5. Process Synchronization</h2><p>Coordination is required when concurrent execution accesses shared data.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Critical Section</h3><p>A critical section is the part of a program that accesses shared resources. A correct solution aims for mutual exclusion, progress and bounded waiting.</p><div class=\"flow\"><div class=\"node\">Entry</div><div class=\"arrow\">→</div><div class=\"node\">Critical Section</div><div class=\"arrow\">→</div><div class=\"node\">Exit</div><div class=\"arrow\">→</div><div class=\"node\">Remainder</div></div></article>\n  <article class=\"card\"><h3>Mutex & Semaphore</h3><p><b>Mutex:</b> ownership-based lock commonly used for mutual exclusion.</p><p><b>Semaphore:</b> synchronization primitive represented by a counter and atomic wait/signal operations.</p><div class=\"lock\">LOCK</div></article>\n  <article class=\"card\"><h3>Classic problems</h3><ul><li>Producer–Consumer / Bounded Buffer</li><li>Readers–Writers</li><li>Dining Philosophers</li></ul></article>\n  <article class=\"card\"><h3>Race condition</h3><p>When the result depends on the timing/order of concurrent accesses to shared state. Synchronization controls the order of critical operations.</p></article>\n </div>\n</section>\n\n<section id=\"deadlock\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>6. Deadlocks</h2><p>A set of processes can become permanently blocked while waiting for resources held by each other.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Four necessary conditions</h3><ol><li>Mutual exclusion</li><li>Hold and wait</li><li>No preemption</li><li>Circular wait</li></ol><div class=\"note\">Breaking at least one necessary condition can prevent deadlock.</div></article>\n  <article class=\"card\"><h3>Prevention vs Avoidance vs Detection</h3><p><b>Prevention:</b> constrain resource allocation so a necessary condition cannot hold.</p><p><b>Avoidance:</b> make allocation decisions while maintaining a safe state.</p><p><b>Detection:</b> allow deadlock, then detect and recover.</p></article>\n </div>\n <div class=\"viz\"><h3>Resource Allocation — Circular Wait</h3><div class=\"stage deadlock\"><div class=\"ring\"></div><div class=\"dnode d1\">P1 holds R1</div><div class=\"dnode d2\">R1 waits P2</div><div class=\"dnode d3\">P2 holds R2</div><div class=\"dnode d4\">R2 waits P1</div></div></div>\n <div class=\"card\" style=\"margin-top:15px\"><h3>Banker\'s Algorithm</h3><p>The system grants a request only if the resulting state remains safe. Core data: <b>Available</b>, <b>Max</b>, <b>Allocation</b>, and <b>Need = Max − Allocation</b>.</p><div class=\"flow\"><div class=\"node\">Available</div><div class=\"arrow\">→</div><div class=\"node\">Need check</div><div class=\"arrow\">→</div><div class=\"node\">Pretend allocate</div><div class=\"arrow\">→</div><div class=\"node\">Safe sequence?</div></div></div>\n</section>\n\n<section id=\"memory\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>7. Memory Management</h2><p>Memory management maps processes to physical memory while providing protection and efficient allocation.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Logical vs Physical Address</h3><div class=\"flow\"><div class=\"node\">CPU</div><div class=\"arrow\">→</div><div class=\"node\">Logical Address</div><div class=\"arrow\">→</div><div class=\"node\">MMU</div><div class=\"arrow\">→</div><div class=\"node\">Physical Address</div></div></article>\n  <article class=\"card\"><h3>Fragmentation</h3><p><b>Internal fragmentation:</b> unused space inside an allocated block.</p><p><b>External fragmentation:</b> free memory exists but is split into small non-contiguous pieces.</p></article>\n  <article class=\"card\"><h3>Paging</h3><p>Logical memory is divided into fixed-size pages; physical memory is divided into frames. A page table maps page numbers to frame numbers.</p><div class=\"frames\"><div class=\"frame\">F0</div><div class=\"frame hot\">F1</div><div class=\"frame\">F2</div><div class=\"frame\">F3</div></div></article>\n  <article class=\"card\"><h3>Segmentation</h3><p>A logical address is represented as a segment number and offset. Segments correspond to logical program units such as code, data or stack.</p></article>\n </div>\n</section>\n\n<section id=\"virtual\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>8. Virtual Memory</h2><p>Virtual memory lets processes use an address space larger than available physical RAM.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Page Fault</h3><div class=\"flow\"><div class=\"node\">Reference Page</div><div class=\"arrow\">→</div><div class=\"node\">Page Table</div><div class=\"arrow\">→</div><div class=\"node\">Not in RAM</div><div class=\"arrow\">→</div><div class=\"node\">Page Fault</div></div><p>The OS loads the required page from secondary storage and updates the page table.</p></article>\n  <article class=\"card\"><h3>TLB</h3><p>The Translation Lookaside Buffer caches recent page-table translations. A TLB hit avoids an additional page-table lookup.</p></article>\n </div>\n <div class=\"viz\"><div class=\"viz-head\"><h3>Page Replacement Visualizer</h3><span class=\"badge yellow\">FIFO / LRU concept</span></div><div class=\"controls\"><button onclick=\"pageDemo(\'FIFO\')\">FIFO</button><button onclick=\"pageDemo(\'LRU\')\">LRU</button><button onclick=\"resetPages()\">Reset</button></div><div class=\"frames\" id=\"pageFrames\"><div class=\"frame\">—</div><div class=\"frame\">—</div><div class=\"frame\">—</div></div><p id=\"pageInfo\" style=\"color:#9aabc2\">Click an algorithm to step through reference pages.</p></div>\n</section>\n\n<section id=\"files\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>9. File Systems</h2><p>The file system organizes persistent data into files, directories and metadata.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>File operations</h3><div class=\"flow\"><div class=\"node\">Create</div><div class=\"node\">Open</div><div class=\"node\">Read</div><div class=\"node\">Write</div><div class=\"node\">Close</div><div class=\"node\">Delete</div></div></article>\n  <article class=\"card\"><h3>Directory structures</h3><div class=\"file-tree\"><span class=\"dir\">/home</span><br>├── <span class=\"dir\">user/</span><br>│ ├── <span class=\"file\">notes.txt</span><br>│ └── <span class=\"file\">app.js</span><br>└── <span class=\"dir\">projects/</span></div></article>\n  <article class=\"card\"><h3>File allocation</h3><p><b>Contiguous:</b> file occupies consecutive blocks.</p><p><b>Linked:</b> each block points to the next block.</p><p><b>Indexed:</b> an index block stores pointers to file blocks.</p></article>\n  <article class=\"card\"><h3>Inode concept</h3><p>Unix-like file systems use inode metadata to describe a file, including ownership, permissions, timestamps, size and pointers to data blocks.</p></article>\n </div>\n</section>\n\n<section id=\"disk\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>10. Disk Management</h2><p>Disk scheduling determines the order in which pending disk requests are served.</p></div></div>\n <div class=\"grid\"><article class=\"card\"><h3>Algorithms</h3><p><span class=\"badge cyan\">FCFS</span> Serve in arrival order.</p><p><span class=\"badge yellow\">SSTF</span> Serve the nearest request.</p><p><span class=\"badge green\">SCAN</span> Move like an elevator toward one end, then reverse.</p><p><span class=\"badge\">C-SCAN</span> Move in one direction and wrap around.</p><p><span class=\"badge\">LOOK / C-LOOK</span> Similar ideas but stop at the final pending request.</p></article>\n <article class=\"card\"><h3>Why scheduling matters</h3><p>Seek time can dominate disk access. Reordering requests can reduce head movement and improve throughput, though policies may introduce fairness or starvation trade-offs.</p></article></div>\n <div class=\"viz\"><h3>Animated Disk Head</h3><div class=\"disk\"><div class=\"disk-head\"></div></div><div class=\"track-labels\"><span>0</span><span>25</span><span>50</span><span>75</span><span>100</span></div></div>\n</section>\n\n<section id=\"io\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>11. I/O Systems</h2><p>The OS coordinates CPU, memory and external devices.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Interrupt-driven I/O</h3><div class=\"flow\"><div class=\"node\">Device</div><div class=\"arrow\">→</div><div class=\"node\">Interrupt</div><div class=\"arrow\">→</div><div class=\"node\">CPU</div><div class=\"arrow\">→</div><div class=\"node\">ISR</div></div></article>\n  <article class=\"card\"><h3>DMA</h3><p>Direct Memory Access allows a controller to transfer blocks between a device and memory with limited CPU involvement.</p></article>\n  <article class=\"card\"><h3>Buffering, Caching, Spooling</h3><p><b>Buffering:</b> temporary data area for rate mismatch.</p><p><b>Caching:</b> retain frequently/recently used data for faster access.</p><p><b>Spooling:</b> queue work for a device, classically print jobs.</p></article>\n </div>\n</section>\n\n<section id=\"security\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>12. Protection & Security</h2><p>Security controls who can access resources and what operations they may perform.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Authentication vs Authorization</h3><div class=\"flow\"><div class=\"node\">Identity</div><div class=\"arrow\">→</div><div class=\"node\">Authentication</div><div class=\"arrow\">→</div><div class=\"node\">Authorization</div><div class=\"arrow\">→</div><div class=\"node\">Resource</div></div><p>Authentication establishes identity; authorization determines permitted actions.</p></article>\n  <article class=\"card\"><h3>Least Privilege</h3><p>Give a process, user or service only the permissions required to perform its task. This limits the impact of compromise or mistakes.</p></article>\n </div>\n</section>\n\n<section id=\"linux\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>13. Linux / Unix Concepts</h2><p>Practical OS concepts through a Unix-like system model.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Useful commands</h3><div class=\"code\"><span class=\"comment\"># processes</span>\nps aux\ntop\nkill PID\n\n<span class=\"comment\"># files</span>\nls -la\ncd project\nmkdir demo\ncat file.txt\n\n<span class=\"comment\"># permissions</span>\nchmod 755 script.sh\nchown user:group file</div></article>\n  <article class=\"card\"><h3>Process & filesystem model</h3><div class=\"flow\"><div class=\"node\">Shell</div><div class=\"arrow\">→</div><div class=\"node\">System Call</div><div class=\"arrow\">→</div><div class=\"node\">Kernel</div><div class=\"arrow\">→</div><div class=\"node\">Resource</div></div><p>Linux exposes many kernel objects and runtime details through virtual file systems such as <code>/proc</code>.</p></article>\n </div>\n</section>\n\n<section id=\"advanced\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>14. Advanced OS Concepts</h2><p>Concepts used in modern servers, cloud platforms and embedded systems.</p></div></div>\n <div class=\"grid\">\n  <article class=\"card\"><h3>Virtualization</h3><p>A hypervisor provides an abstraction that allows multiple virtual machines to share physical hardware.</p><div class=\"flow\"><div class=\"node\">VM 1</div><div class=\"node\">VM 2</div><div class=\"node\">VM 3</div><div class=\"arrow\">↓</div><div class=\"node\">Hypervisor</div><div class=\"arrow\">↓</div><div class=\"node\">Hardware</div></div></article>\n  <article class=\"card\"><h3>Containers</h3><p>Containers isolate application processes while sharing the host kernel. They are lighter than full virtual machines because they do not normally require a separate guest kernel.</p></article>\n  <article class=\"card\"><h3>Real-Time OS</h3><p>RTOS designs prioritize predictable response and meeting timing constraints. Hard and soft real-time systems differ in the consequences of missing deadlines.</p></article>\n  <article class=\"card\"><h3>Multiprocessor & Distributed Systems</h3><p>Multiprocessor systems use multiple processing units in one computer system. Distributed systems coordinate independent machines through communication networks.</p></article>\n </div>\n</section>\n\n<section id=\"cheat\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>15. Exam Cheat Sheet</h2><p>Fast revision of high-frequency formulas and concepts.</p></div></div>\n <div class=\"card\"><table>\n <tr><th>Topic</th><th>Remember</th></tr>\n <tr><td>Process</td><td>Program in execution; PCB stores process management information.</td></tr>\n <tr><td>Context switch</td><td>Save state of one process/thread and restore another.</td></tr>\n <tr><td>Waiting time</td><td>Turnaround − Burst time.</td></tr>\n <tr><td>Turnaround</td><td>Completion − Arrival.</td></tr>\n <tr><td>Paging</td><td>Pages map to fixed-size physical frames.</td></tr>\n <tr><td>Page fault</td><td>Referenced page is not currently in physical memory.</td></tr>\n <tr><td>TLB</td><td>Cache of recent address translations.</td></tr>\n <tr><td>Deadlock</td><td>Mutual exclusion + hold/wait + no preemption + circular wait.</td></tr>\n <tr><td>Semaphore</td><td>Synchronization primitive supporting atomic wait/signal operations.</td></tr>\n <tr><td>DMA</td><td>Device controller transfers data with reduced CPU involvement.</td></tr>\n </table></div>\n</section>\n\n<section id=\"quiz\" class=\"section reveal\">\n <div class=\"section-head\"><div><h2>16. Practice Quiz</h2><p>Test your understanding.</p></div></div>\n <div id=\"quizBox\" class=\"grid\"></div>\n <div class=\"card\" style=\"margin-top:15px\"><b>Progress</b><div class=\"progress\"><span id=\"quizProgress\"></span></div><p id=\"score\" style=\"color:#9aabc2\">0 / 5 answered correctly</p></div>\n</section>\n<footer>Operating Systems — Interactive Notes 2026 · Standalone HTML · Visualize → Explain → Interact → Practice</footer>\n</main>\n</div>\n\n<script>\nconst qs=s=>document.querySelector(s), qsa=s=>[...document.querySelectorAll(s)];\n\nconst procNames=[\'P1\',\'P2\',\'P3\',\'P4\']; let procTimer;\nfunction resetProcessDemo(){\n clearInterval(procTimer); qs(\'#readyQ\').innerHTML=procNames.map(x=>\'<span class=\"process\">\'+x+\'</span>\').join(\'\');\n qs(\'#cpu\').textContent=\'CPU · idle\'; qs(\'#doneQ\').innerHTML=\'\';\n}\nfunction runProcessDemo(){\n resetProcessDemo(); let i=0;\n procTimer=setInterval(()=>{\n  if(i>0){qs(\'#doneQ\').insertAdjacentHTML(\'beforeend\',\'<span class=\"process done\">\'+procNames[i-1]+\'</span>\')}\n  qsa(\'#readyQ .process\').forEach(x=>x.classList.remove(\'running\'));\n  if(i<procNames.length){\n   const p=qsa(\'#readyQ .process\')[0];\n   if(p){p.classList.add(\'running\');qs(\'#cpu\').textContent=\'CPU · \'+p.textContent}\n   i++;\n  }else{clearInterval(procTimer);qs(\'#cpu\').textContent=\'CPU · idle\'}\n },900);\n}\n\nfunction runRR(){\n const q=Math.max(1,+qs(\'#quantum\').value||2), jobs=[[\'P1\',5],[\'P2\',4],[\'P3\',2]];\n let t=0, out=[], arr=jobs.map(x=>[x[0],x[1]]);\n while(arr.some(x=>x[1]>0)){\n  for(const x of arr) if(x[1]>0){const run=Math.min(q,x[1]);out.push([x[0],run,t]);x[1]-=run;t+=run}\n }\n qs(\'#gantt\').innerHTML=out.map(x=>\'<span style=\"flex:\'+x[1]+\'\">\'+x[0]+\'<small style=\"font-size:10px;display:block\">\'+x[2]+\'–\'+(x[2]+x[1])+\'</small></span>\').join(\'\');\n qs(\'#schedInfo\').textContent=\'Quantum \'+q+\' · Total CPU time \'+t+\' units · Each process receives CPU slices in round-robin order.\';\n}\n\nlet pageState={refs:[1,2,3,4,1,5,2,1,3,4],i:0,frames:[],last:[]};\nfunction resetPages(){pageState.i=0;pageState.frames=[];pageState.last=[];qs(\'#pageFrames\').innerHTML=\'<div class=\"frame\">—</div><div class=\"frame\">—</div><div class=\"frame\">—</div>\';qs(\'#pageInfo\').textContent=\'Reference string: 1 2 3 4 1 5 2 1 3 4\'}\nfunction pageDemo(mode){\n resetPages(); let steps=0;\n const timer=setInterval(()=>{\n  if(pageState.i>=pageState.refs.length){clearInterval(timer);return}\n  const p=pageState.refs[pageState.i++]; let hit=pageState.frames.includes(p);\n  if(!hit){\n   if(pageState.frames.length<3) pageState.frames.push(p);\n   else if(mode===\'FIFO\') pageState.frames.shift(),pageState.frames.push(p);\n   else {\n    let idx=pageState.frames.map(x=>pageState.last.lastIndexOf(x));\n    let replace=idx.indexOf(Math.min(...idx)); pageState.frames[replace]=p;\n   }\n  }\n  pageState.last.push(p); steps++;\n  qs(\'#pageFrames\').innerHTML=pageState.frames.map((x,j)=>\'<div class=\"frame \'+(hit?\'\':\'hot\')+\'\">\'+x+\'</div>\').join(\'\');\n  qs(\'#pageInfo\').textContent=mode+\' · reference \'+p+\' · \'+(hit?\'HIT\':\'PAGE FAULT\')+\' · step \'+steps;\n },650);\n}\n\nconst questions=[\n [\'Which structure stores process management information?\',[\'PCB\',\'TLB\',\'Inode\',\'DMA\'],\'PCB\'],\n [\'Which scheduling algorithm uses a time quantum?\',[\'SJF\',\'Round Robin\',\'FCFS\',\'SCAN\'],\'Round Robin\'],\n [\'Which condition is necessary for deadlock?\',[\'Caching\',\'Circular wait\',\'DMA\',\'Paging\'],\'Circular wait\'],\n [\'What does a TLB cache?\',[\'Files\',\'CPU instructions\',\'Address translations\',\'Disk blocks\'],\'Address translations\'],\n [\'What does DMA reduce?\',[\'File size\',\'CPU involvement in data transfer\',\'RAM capacity\',\'Process count\'],\'CPU involvement in data transfer\']\n];\nlet score=0,answered=0;\nqs(\'#quizBox\').innerHTML=questions.map((q,i)=>`<article class=\"card quiz\"><h3>${i+1}. ${q[0]}</h3>${q[1].map(o=>`<button class=\"option\" onclick=\"answer(this,\'${o.replace(/\'/g,\"\\\\\'\")}\',\'${q[2].replace(/\'/g,\"\\\\\'\")}\')\">${o}</button>`).join(\'\')}<div class=\"answer\" id=\"ans${i}\"></div></article>`).join(\'\');\nfunction answer(btn,val,correct){\n const box=btn.closest(\'.quiz\'), ans=box.querySelector(\'.answer\');\n if(box.dataset.done)return;box.dataset.done=1;answered++;\n if(val===correct){score++;btn.style.borderColor=\'#34d399\';btn.style.background=\'#0c2b25\';ans.textContent=\'Correct — \'+correct+\'.\'}\n else {btn.style.borderColor=\'#fb7185\';btn.style.background=\'#321827\';ans.textContent=\'Correct answer: \'+correct+\'.\'}\n qs(\'#score\').textContent=score+\' / 5 answered correctly\';qs(\'#quizProgress\').style.width=(answered/5*100)+\'%\';\n}\n\nqs(\'#search\').addEventListener(\'input\',e=>{\n const term=e.target.value.toLowerCase();\n qsa(\'main .section\').forEach(s=>{s.style.display=(!term||s.innerText.toLowerCase().includes(term))?\'\':\'none\'});\n});\nconst observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add(\'show\')}),{threshold:.08});\nqsa(\'.reveal\').forEach(x=>observer.observe(x));\nresetProcessDemo();resetPages();\n</script>\n</body>\n</html>',0,0.00,199.00,49.00,NULL,'ALL_CENTRES','CENTER_PURCHASE',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,32,'2026-10-02 17:21:44','2026-10-04 13:33:40',20.00),(9,'TEST','test-68','Science','SBDBSF',NULL,'/uploads/branding/img-1791090019658-704.pdf','PDF','0.9 MB','',1,0.00,0.00,0.00,NULL,'SELECTED_CENTRES','BOTH',NULL,'PUBLISHED',NULL,1,'center',1,0,0,'2026-10-04 05:00:19','2026-10-04 14:42:25',20.00),(10,'Free E-Note 1: Basic Math Formulas',NULL,'Mathematics','A comprehensive cheat sheet for basic mathematical formulas and operations.',NULL,NULL,'HTML','2.5 MB','<h1>Basic Math Formulas</h1><p>Here are some basic formulas you should know for your exams...</p>',1,0.00,0.00,0.00,NULL,'ALL_CENTRES','BOTH',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,2,'2026-10-04 13:33:37','2026-10-04 15:49:19',20.00),(11,'Free E-Note 2: English Grammar Basics',NULL,'English','Learn the foundational rules of English grammar with easy examples.',NULL,NULL,'HTML','2.5 MB','<h1>English Grammar Basics</h1><p>Nouns, Verbs, Adjectives, and more! Let us review the fundamentals...</p>',1,0.00,0.00,0.00,NULL,'ALL_CENTRES','BOTH',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,11,'2026-10-04 13:33:37','2026-10-11 12:51:32',20.00),(12,'Free E-Note 3: Daily Current Affairs (Oct 2026)',NULL,'Current Affairs','Top headlines and important news summaries for October 2026.',NULL,NULL,'HTML','2.5 MB','<h1>Current Affairs - Oct 2026</h1><p>Top national and international news summaries for competitive exams...</p>',1,0.00,0.00,0.00,NULL,'ALL_CENTRES','BOTH',NULL,'PUBLISHED',NULL,1,'admin',NULL,0,8,'2026-10-04 13:33:37','2026-10-04 16:07:20',20.00),(13,'Premium E-Note 1: Advanced P